/** Contrato de S500L019SDOS que los clientes de S500 consumen a través de S500L020SDOS. */
public interface ConsultaSaldos {
    int contrato(byte[] entrada, byte[] salida);       // S500L020CONTRATO
    int sdoParNac(byte[] entrada, byte[] salida);      // S500L020SDOPARNAC
    int edoCtaAho(byte[] entrada, byte[] salida);      // S500L020EDOCTAAHO
    int compend(byte[] entrada, byte[] salida);        // S500L020COMPEND
    int pagpend(byte[] entrada, byte[] salida);        // S500L020PAGPEND
    int pagpend2(byte[] entrada, byte[] salida);       // S500L020PAGPEND2
    void fecCont(byte[] entrada);                      // S500L020FECCONT: sin valor de retorno
    int tipoProc(byte[] entrada);                      // S500L020TIPO_PROC
    int fechaClona(byte[] entrada);                    // S500L020FECHACLONA
    // ... 11 más, uno por EXPORT
}

/** Los clientes inyectan siempre la fachada; la implementación real se puede cambiar en caliente. */
@Primary
@Service
class ConsultaSaldosFachada implements ConsultaSaldos, SmartLifecycle {
    // PROC_LEVANTA en start(); FREEZE(CONTROL, PROC_CONTROL) equivale a que el bean
    // permanezca vivo mientras el contexto exista y atienda operaciones de control.
}

static final int REINTENTE_MAS_TARDE = 5;              // RESULT 05 del catálogo de L019

private final AtomicReference<ConsultaSaldos> destino;  // LIGACALL; null = enlace suspendido

ConsultaSaldosFachada(@Qualifier("s500L019") ConsultaSaldos real) {
    this.destino = new AtomicReference<>(real);
}

/** S500L020CONTRATO: los 20 procedimientos tienen exactamente esta forma. */
@Override
public int contrato(byte[] entrada, byte[] salida) {
    ConsultaSaldos d = destino.get();                     // IF B_LLAMAL020
    return (d != null) ? d.contrato(entrada, salida)       // S500L020CONTRATO_C(...)
                       : REINTENTE_MAS_TARDE;
}

/** S500L020FECCONT es PROCEDURE sin tipo: no puede devolver 05. */
@Override
public void fecCont(byte[] entrada) {
    ConsultaSaldos d = destino.get();
    if (d != null) {
        d.fecCont(entrada);
        return;
    }
    // El original no hace nada (ELSE comentado). Para no ocultarlo se lanza una excepción
    // que el cliente puede tratar como el 05 de los demás procedimientos.
    throw new EnlaceSuspendidoException("S500L020FECCONT con enlace a L019 suspendido");
}

# application.yml
s500:
  saldos:
    implementacion: s500L019        # identificador CTLVER "S500L019SDOS"

// ---------------------------------------------------------------------------
@Component
@RequiredArgsConstructor
class ResolutorLibreria {

    private final ApplicationContext ctx;
    private final SaldosProperties props;

    /** PROC_DAME_TIT_S500L019: DAME_TIT("S500L019SDOS") y REPLACE LIGACALL.TITLE. */
    Optional<ConsultaSaldos> resuelve() {
        try {
            return Optional.of(ctx.getBean(props.implementacion(), ConsultaSaldos.class));
        } catch (BeansException e) {
            log.error("ERROR CALL CTLVER S500L019SDOS", e);   // DF_DISPLAY y sigue
            return Optional.empty();
        }
    }
}

# application.yml
s500:
  saldos:
    version-esperada: 25MTP002
    hosts-sin-validacion: [ACYPBETA, CACYPBET]    # B_HOST_CDL

// ---------------------------------------------------------------------------
@Component
@RequiredArgsConstructor
class VersionPropiaValidator {

    private final ControlVersiones ctlver;        // CHECAME de CTLVERS
    private final SaldosProperties props;

    void valida(String host) {
        if (props.hostsSinValidacion().contains(host)) {
            return;                                // ambiente de desarrollo o beta
        }
        if (!ctlver.checame("S500L020SDOS", props.versionEsperada())) {
            // MYSELF.STATUS := -1
            throw new VersionNoAutorizadaException("ERROR MI NOMBRE NO CORRESP. AL DE CTLVER");
        }
    }
}

/** PROC_LEVANTA. */
@Override
public void start() {
    validator.valida(host);                       // CHECA_VERSION
    resolutor.resuelve().ifPresent(real -> {      // PROC_DAME_TIT_S500L019
        real.levanta();                           // LEVANTA_C
        destino.set(real);                        // B_LLAMAL020 := TRUE
    });
}

/** BAJA: en el original repite CHECA_VERSION y pone la bandera en TRUE antes de BAJA_C. */
@Override
public void stop() {
    ConsultaSaldos real = destino.getAndSet(null);
    if (real != null) {
        real.baja();                              // BAJA_C
    }
}

@Component
@Endpoint(id = "enlacel019")
@RequiredArgsConstructor
class EnlaceSaldosEndpoint {

    private final ConsultaSaldosFachada fachada;
    private final ResolutorLibreria resolutor;

    @ReadOperation                                   // HI 1
    public String estado() {
        return fachada.enlaceActivo() ? "STATUS ACCESO A L019: CON" : "STATUS ACCESO A L019: SIN";
    }

    @WriteOperation                                  // HI 1920
    public String suspende() {
        ConsultaSaldos anterior = fachada.suspende(); // destino := null; desde aquí se responde 05
        // DELINKLIBRARY(LIGACALL): la instancia anterior se libera cuando terminen sus llamadas
        return "SE SUSPENDE LIGA A L019";
    }

    @WriteOperation                                  // HI 1950
    public String liga() {
        resolutor.resuelve().ifPresent(real -> {
            real.levanta();                          // LEVANTA_C
            fachada.conecta(real);                   // B_LLAMAL020 := TRUE
        });
        return "SE HACE LIGA A L019";
    }
}
